from CoolProp.CoolProp import PropsSI

FLUIDO = "Water"
_NOMI = {"T": "T", "s": "S", "x": "Q", "h": "H"}


def stato(p, **kw):
    (nome, valore), = kw.items()
    k = _NOMI[nome]
    return {
        "p": p,
        "T": PropsSI("T", "P", p, k, valore, FLUIDO),
        "h": PropsSI("H", "P", p, k, valore, FLUIDO),
        "s": PropsSI("S", "P", p, k, valore, FLUIDO),
    }
